import fs from 'node:fs';
import { compiledOverrides, loadHeroI18nCatalog, validateHeroI18nCatalog } from './lib/official-hero-catalog.mjs';
import { applyInGameHeroOverridesToCatalog, loadInGameHeroOverrides, validateInGameHeroOverrides } from './lib/in-game-hero-overrides.mjs';

function compileHeroNames() {
  const names = JSON.parse(fs.readFileSync(new URL('../data/locales/hero-names.json', import.meta.url), 'utf8'));
  const official = Object.fromEntries(['ja', 'zh-CN', 'ko', 'es'].map(locale => [locale, names[locale] || {}]));
  const output = [
    '// Generated by scripts/generate-hero-i18n.mjs from data/locales/hero-names.json.',
    '// Official sync updates this file together with hero detail snapshots.',
    '',
    `export const LOCALIZED_HERO_NAMES = Object.freeze(${JSON.stringify(official, null, 2)});`,
    '',
  ].join('\n');
  fs.writeFileSync(new URL('../js/i18n-hero-names.js', import.meta.url), output);
}

export function compileHeroI18n({ requireFullOfficial = false, requireFullVietnamese = false } = {}) {
  const inGameOverrides = loadInGameHeroOverrides();
  validateInGameHeroOverrides(inGameOverrides);
  const catalog = applyInGameHeroOverridesToCatalog(loadHeroI18nCatalog(), inGameOverrides);
  const validation = validateHeroI18nCatalog(catalog, { requireFullOfficial, requireFullVietnamese });
  const overrides = compiledOverrides(catalog);
  const metadata = { schemaVersion: catalog.schemaVersion, policy: catalog.policy, coverage: validation.coverage, generatedFrom: ['data/locales/official-hero-details.json', 'data/locales/in-game-hero-overrides.json'] };
  const banner = [
    '// Generated by scripts/generate-hero-i18n.mjs.',
    '// DO NOT add machine-generated or heuristic translations here.',
    '// Official locales contain validated website snapshots plus exact fields manually checked in the released game client when available.',
    '// Missing records intentionally fall back to canonical English.',
    '',
  ].join('\n');
  const output = `${banner}export const HERO_I18N_METADATA = Object.freeze(${JSON.stringify(metadata, null, 2)});\n\nexport const FULL_HERO_DETAIL_OVERRIDES = Object.freeze(${JSON.stringify(overrides, null, 2)});\n`;
  fs.writeFileSync(new URL('../js/i18n-hero-details.js', import.meta.url), output);
  compileHeroNames();
  return validation;
}

const isCli = process.argv[1] && new URL(`file://${process.argv[1]}`).href === import.meta.url;
if (isCli) {
  const requireFullOfficial = process.argv.includes('--require-full-official');
  const requireFullVietnamese = process.argv.includes('--require-full-vi');
  const result = compileHeroI18n({ requireFullOfficial, requireFullVietnamese });
  console.log(`Compiled verified hero i18n snapshots: ${Object.entries(result.coverage).map(([locale, count]) => `${locale}=${count}`).join(', ')}.`);
}
